mapper.select:
select
mn.* from Sec_Project mn
left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join Sec_Open_Complaints soc on soc.Sec_Id=sec.Sec_Id where soc.id=#{id}

select
sec.Sec_Name as secName,
sec.Sec_Code as secCode,
sec.Sec_Type as secType,
mn.*
from Sec_Open_Complaints mn
left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id

    
        and mn.Te_Id = #{params.teId}
    
    
        and mn.Soc_Question = #{params.socQuestion}
    
    
        and mn.Sec_Id = #{params.secId}
    
    
        and sec.Sec_Bidding_Type = #{params.secBiddingType}
    
    
        and sec.Sec_Name like concat('%',#{params.secName},'%')
    
    
        and mn.Soc_Questioner_Telephone like concat('%',#{params.socQuestionerTelephone},'%')
    
    
        and mn.Soc_Question_Question like concat('%',#{params.socQuestionQuestion},'%')
    
    
        and mn.Soc_Respondent like concat('%',#{params.socRespondent},'%')
    
    
        and mn.Soc_Reply_Content like concat('%',#{params.socReplyContent},'%')
    
    
        and mn.Soc_Remarks like concat('%',#{params.socRemarks},'%')
    
    
        and mn.Create_Uname like concat('%',#{params.createUname},'%')
    
    
        and mn.create_Time > #{params.createTimeStart}
    
    
        and mn.create_Time < #{params.createTimeEnd}
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time desc
